import { createHash } from 'node:crypto'
import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const root = new URL('../', import.meta.url)
const lockText = await readFile(new URL('package-lock.json', root), 'utf8')
const lock = JSON.parse(lockText)
const rows = Object.entries(lock.packages).filter(([path]) => path).sort(([a], [b]) => a.localeCompare(b, 'en'))
const lines = [
  '# Locked dependency licenses', '',
  'Generated by `npm run licenses:update` from `package-lock.json`; do not edit by hand.', '',
  `Lockfile SHA-256: \`${createHash('sha256').update(lockText).digest('hex')}\``, '',
  'This is a metadata inventory, not a replacement for upstream copyright and license texts.',
  'Optional entries cover other operating systems and may not be installed on this machine.',
  'Development dependencies are included for transparency. The source repository does not vendor these packages.',
  'See [third-party notices](../THIRD_PARTY_NOTICES.md) and the license bundle emitted with production builds.', '',
  '| Package | Version | SPDX license expression | Use | Locked source |',
  '| --- | --- | --- | --- | --- |',
]
for (const [path, entry] of rows) {
  const name = path.split('node_modules/').at(-1)
  if (!entry.license || !entry.version || !entry.resolved) throw new Error(`Missing license/version/source: ${path}`)
  const url = new URL(entry.resolved)
  if (url.protocol !== 'https:' || url.hostname !== 'registry.npmjs.org' || url.username || url.password) throw new Error(`Review non-registry dependency: ${path}`)
  const use = `${entry.dev ? 'Development' : 'Runtime'}${entry.optional ? ', optional' : ''}`
  lines.push(`| ${name} | ${entry.version} | ${entry.license} | ${use} | [npm tarball](${url.href}) |`)
}
lines.push('')
const output = new URL('docs/dependency-licenses.md', root)
await writeFile(output, lines.join('\n'))
console.log(`Recorded ${rows.length} locked dependencies in ${fileURLToPath(output)}`)
